-- BACKLOG-3473 MUTANT (generated by generate.mjs from the shipped files; do not hand-edit)
-- the seed floor uses <= (an org exactly at min_tier is not seeded)
-- targets: c42
-- Runs INSIDE a control's transaction, after the prelude; rolled back with it.

CREATE OR REPLACE FUNCTION public._seed_checklists_on_plan_write()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF public.tier_rank((SELECT p.tier FROM public.plans p WHERE p.id = NEW.plan_id))
     <= public.tier_rank((SELECT fd.min_tier FROM public.feature_definitions fd
                          WHERE fd.key = 'transaction_checklists')) THEN
    RETURN NULL;
  END IF;
  PERFORM public._seed_org_checklist_templates(NEW.organization_id);
  RETURN NULL;
END
$$;

DO $proof$
BEGIN
  IF NOT (pg_get_functiondef('public._seed_checklists_on_plan_write()'::regprocedure) LIKE '%<= public.tier_rank((SELECT fd.min_tier%') THEN
    RAISE EXCEPTION 'MUTATION NOT APPLIED';
  END IF;
END
$proof$;
SELECT 'MUTATION APPLIED: ' || ('floor <=') AS mutation;
